// E2B colour system v0.20.4-draft · generated by build.py — edit SPEC there, not this file
// Mintlify renders code with Shiki's css-variables theme, which gives declarations (const, async, function), keywords
// (await, return, try) and operators one colour. This applies the system's two word rules after load and on navigation.
(() => {
  const DECLARATIONS = new Set(["const", "let", "var", "function", "async", "class", "interface", "type", "enum", "namespace", "declare", "abstract", "extends", "implements", "static", "readonly", "private", "public", "protected", "get", "set", "def", "lambda"]);
  const OPERATOR = /^[=+\-*/%<>!&|?:^~.]+$/;
  const run = () => document.querySelectorAll('span[style*="token-keyword"]:not([data-e2b-code])').forEach((s) => {
    s.dataset.e2bCode = "";
    const t = s.textContent.trim();
    const role = DECLARATIONS.has(t) ? "declaration" : OPERATOR.test(t) ? "operator" : null;
    if (!role) return;
    // Mintlify renders dual-theme code and forces dark with html.dark .shiki span { color: var(--shiki-dark) !important },
    // so set the colour and both theme variables.
    const c = `var(--color-code-${role})`;
    s.style.color = c;
    s.style.setProperty("--shiki-dark", c);
    s.style.setProperty("--shiki-light", c);
  });
  run();
  new MutationObserver(run).observe(document.body, { childList: true, subtree: true });
})();
